      fullDesc: "آلدِرین نخستین نژادی بودند که الهه‌ی آئلیث به آن‌ها برکت داد — جاودانگی و پیوندی ناگسسته با تار و پود جادو. پنج هزار سال بر آرکِیا همچون شاهانِ فیلسوف فرمان راندند و در جنگل نقره‌ای، میان درختان غول‌آسا، شهرهایی از بلور و نور ستاره ساختند. آن‌ها نگهبانان رون‌ها بودند، تعبیرکنندگان پیشگویی، و پاسداران خودخوانده‌ی جهان. اما جاودانگی نفرینی است در لباس هدیه: آلدِرین فراموش کرده‌اند چگونه تغییر کنند. فراموش کرده‌اند چگونه امید داشته باشند. و اکنون، سه هزاره پس از بند‌کشیدن آئلیث، خاموش‌خاموش رو به نابودی‌اند — نه از جنگ یا طاعون، بلکه از حقیقتی ساده و ویران‌کننده: صد و شصت سال است که هیچ کودک آلدِرینی زاده نشده. جز یکی. سپیده‌ی آخر. و او نمی‌خواهد که باشد. آلدِرین مردمی‌اند که منتظر مرگ‌اند — اما مردمی‌اند که از اعترافش سر باز می‌زنند.",
      secret: "آلدِرین از علل طبیعی نمی‌میرند. الهه‌شان، آئلیث، هنوز زنده است — زندانی‌شده در زیر جنگل نقره‌ای به دست فرزندان خودش، که از داوری‌اش بیم داشتند. تا زمانی که او در بند بماند، آلدِرین نازا خواهند بود. آنان رستگاری خود را زندانی کرده‌اند. و تنها کودک زاده‌شده — آئلوین وِیلور — تنها به این دلیل وجود دارد که بند، برای یک دهه، ترک برداشت.",
