      fullDesc: "کِمیری بازماندگان آزمایشی جادویی کهن‌اند — تلاش جادوگر-پادشاهی دیرین‌مرگ برای آفرینش سربازان کامل، با پیوند دادن روح جانوران بر جان‌های انسانی. آزمایش کامیاب شد. سربازان بی‌نقص بودند. سپس بر آفریننده‌شان شوریدند، و جهان بر آنان شورید. هفت هزار سال، کِمیری به دست هر نژاد دیگری شکار، به بردگی کشیده، و نابود شده‌اند. زنده مانده‌اند چون سازگارند: هر کِمیری بهنگام زادن، چهره‌ای جانوری می‌یابد که توانایی‌های یگانه‌ای به او می‌بخشد. گرگ‌چهره، روباه‌چهره، پرنده‌چهره، مارچهره، یا نادرتر. در گروه‌ها زندگی می‌کنند — واحدهای خانوادگی موقتی — که به‌اندازه‌ی نیاز شکل می‌گیرند و می‌پاشند. میهن ندارند. پایتخت ندارند. تنها یکدیگر را دارند.",
      secret: "کِمیری طاعونی خفته با خود دارند — نفرین جانور — که میان خودشان انتقال نمی‌یابد اما به همه‌ی نژادهای دیگر سرایت می‌کند. افسون مرگ جادوگر-پادشاه، در خونشان تنیده، طوری طراحی شده که آنگاه فعال شود که جمعیت کِمیری زیر هزار افتد. آنان اکنون هزار و چهارصد نفرند. بزرگان می‌دانند. به جوانان نگفته‌اند. زمانشان تمام می‌شود.",
      culture: "کِمیری فرهنگی یکپارچه ندارند؛ تنها تجربه‌ی مشترک آزار دارند. در «گروه‌ها» سازمان می‌یابند — واحدهای خانوادگی موقتی. خالکوبی‌هایشان تزیینی نیست — هر فرار، هر نجات، هر باخت را ثبت می‌کنند. پوست یک کِمیری، زندگی‌نامه‌ی اوست. غذایشان هر چیزی است که بیابند — برای خود جمع‌آوری، شکار، دزدیده. موسیقی‌شان ترانه‌های بقاست — پرسش و پاسخ، شفاهی، با هر گروه تغییر می‌کند.",
